// pullNewHeadLabel is the head as a reader names it: owner/name:branch for a fork, the branch alone otherwise.
func pullNewHeadLabel(data view.PullNewData, branch string) string {
	if data.HeadRepo == "" {
		return branch
	}
	return data.HeadRepo + ":" + branch
}

